SELECT r.sequence, r.id, r.conversation_id, r.role, r.type, r.embedding_index, r.status, r.content, r.preamble, r.turn_id, r.archived, r.created_at, r.updated_at, r.created_by_user_id, r.mode, r.raw_content, r.summary, r.context_summary, r.tags, r.interim, r.elicitation_id, r.parent_message_id, r.superseded_by, r.linked_conversation_id, r.attachment_payload_id, r.elicitation_payload_id, r.tool_name, r.iteration, r.phase FROM (SELECT * FROM  (SELECT c.* , 0 AS should_delete FROM message c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)